struct ResourceStatus {
 size_t vram_total;
 size_t vram_free;
 size_t vram_engine_peak; // gemessen in TB 69
 size_t ram_total;
 size_t ram_free;
 size_t ram_models; // gebunden durch ModelStore
 bool vram_safe; // vram_free > 500 MB
 bool ram_safe; // ram_free > 500 MB
};

class ResourceMonitor {
public:
 void start(); // startet Poll-Thread
 void stop();

 ResourceStatus get_status() const;

 // Callbacks (werden von Monitor-Thread aufgerufen):
 std::function<void()> on_vram_pressure; // → layer_streamer pausiert
 std::function<void()> on_ram_pressure; // → kv_manager trimmt KV-Cache
 std::function<void()> on_buffer_restored;
};

// VRAM: hipMemGetInfo(&free, &total)
// RAM: GlobalMemoryStatusEx (Windows)
```

Bei VRAM-Druck: laufender Chunk-Transfer pausiert, KV-Cache trimmt auf Minimum (H2O).
Bei RAM-Druck: Warnung an Orchestrator, keine neuen Subagent-Loads.
